using System.Drawing.Drawing2D;
using GeoKernel.Examples.Common;
using GeoKernel.NET.WinForms;
namespace GeoKernel.RouteOptimization.Winforms;

public sealed class MainForm : Form
{
    readonly GeoKernelViewerControl viewer = new() { Dock = DockStyle.Fill }; readonly Button reset = new() { Text = "New optimization", AutoSize = true, Enabled = false }, calculate = new() { Text = "Optimize route", AutoSize = true, Enabled = false }; readonly NumericUpDown vehicles = new() { Minimum = 1, Maximum = 1, Value = 1, Dock = DockStyle.Fill }; readonly ListBox routeList = new() { Dock = DockStyle.Fill }, roadList = new() { Dock = DockStyle.Fill }; readonly Label summary = new() { Text = "Select a depot and at least two visits.", Dock = DockStyle.Fill }; readonly ToolStripStatusLabel status = new(); readonly Overlay overlay; OptimizationEngine? engine; IReadOnlySet<int> component = new HashSet<int>(); readonly List<RoutePoint> points = []; readonly List<int> nodes = []; OptimizationResult? result; bool busy;
    public MainForm() { Text = "RouteOptimization"; Width = 1200; Height = 760; StartPosition = FormStartPosition.CenterScreen; var icon = Path.Combine(AppContext.BaseDirectory, "resources", "GeoKernelAppIcon.ico"); if (File.Exists(icon)) Icon = new Icon(icon); var toolbar = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 34, WrapContents = false }; toolbar.Controls.Add(reset); toolbar.Controls.Add(calculate); Legend(toolbar, "Depot", Color.FromArgb(34, 197, 94)); Legend(toolbar, "Visit", Color.FromArgb(245, 158, 11)); var panel = new TableLayoutPanel { Dock = DockStyle.Right, Width = 320, Padding = new Padding(10), RowCount = 7 }; panel.RowStyles.Add(new(SizeType.Absolute, 22)); panel.RowStyles.Add(new(SizeType.Absolute, 85)); panel.RowStyles.Add(new(SizeType.Absolute, 30)); panel.RowStyles.Add(new(SizeType.Absolute, 190)); panel.RowStyles.Add(new(SizeType.Absolute, 25)); panel.RowStyles.Add(new(SizeType.Percent, 100)); panel.Controls.Add(new Label { Text = "Service vehicle routes", Font = new Font(Font, FontStyle.Bold), Dock = DockStyle.Fill }, 0, 0); panel.Controls.Add(summary, 0, 1); var row = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 2 }; row.ColumnStyles.Add(new(SizeType.Percent, 70)); row.ColumnStyles.Add(new(SizeType.Percent, 30)); row.Controls.Add(new Label { Text = "Service vehicles:", Dock = DockStyle.Fill, TextAlign = ContentAlignment.MiddleLeft }, 0, 0); row.Controls.Add(vehicles, 1, 0); panel.Controls.Add(row, 0, 2); panel.Controls.Add(routeList, 0, 3); panel.Controls.Add(new Label { Text = "Road directions", Font = new Font(Font, FontStyle.Bold), Dock = DockStyle.Fill }, 0, 4); panel.Controls.Add(roadList, 0, 5); var bar = new StatusStrip(); bar.Items.Add(status); Controls.Add(viewer); Controls.Add(panel); Controls.Add(toolbar); Controls.Add(bar); overlay = new(viewer); Shown += LoadSample; Move += (_, _) => overlay.SyncBounds(); Resize += (_, _) => overlay.SyncBounds(); FormClosed += (_, _) => overlay.Close(); viewer.VisibleExtentChanged += (_, _) => overlay.Invalidate(); viewer.MapMouseUp += MapClicked; reset.Click += (_, _) => Reset(); calculate.Click += async (_, _) => await Optimize(); routeList.SelectedIndexChanged += (_, _) => SelectVehicle(); roadList.SelectedIndexChanged += (_, _) => SelectRoad(); }
    static void Legend(Control p, string text, Color c) { p.Controls.Add(new Label { Text = "●", ForeColor = c, AutoSize = true, Padding = new Padding(8, 7, 0, 0) }); p.Controls.Add(new Label { Text = text, AutoSize = true, Padding = new Padding(0, 7, 0, 0) }); }
    async void LoadSample(object? s, EventArgs e) { UseWaitCursor = true; status.Text = "Loading Stockholm road network..."; await Task.Yield(); try { viewer.ActiveTool = GeoKernelViewerTool.Pan; var path = SampleData.EnsureSampleFile(new Uri("https://github.com/geokernel-io/GeoKernel.SampleData/releases/download/v1/stockholm.zip"), "stockholm.zip", "stockholm", "stockholm.shp", this); if (string.IsNullOrEmpty(path) || !viewer.AddLayerFile(path)) return; viewer.SetLayerCoordinateSystemPreset(0, GeoKernelCoordinateSystemPreset.Wgs84); viewer.SetCoordinateSystemPreset(GeoKernelCoordinateSystemPreset.WebMercator); viewer.SetLayerStyle(0, new GeoKernelLayerStyle { LineColor = "#718684", LineWidth = 1 }); if (!viewer.BuildRoutingGraphForLayer(0, 1e-6, true, "maxspeed", "name", "oneway", 50)) throw new InvalidOperationException("Routing graph could not be built."); status.Text = "Preparing routing graph..."; var snap = await Task.Run(() => viewer.GetRoutingGraphSnapshot()) ?? throw new InvalidOperationException("Routing graph is unavailable."); var prepared = await Task.Run(() => { var x = new OptimizationEngine(snap.Nodes.Select(n => new RouteNode(n.Id, new(n.Position.X, n.Position.Y))), snap.Edges.Select(a => new RouteEdge(a.Id, a.FromId, a.ToId, a.Distance, a.SpeedKmh, a.Geometry.Select(p => new RoutePoint(p.X, p.Y)).ToArray(), a.Attributes.TryGetValue("name", out var name) ? name?.ToString() ?? "" : ""))); return (x, x.LargestComponent()); }); engine = prepared.x; component = prepared.Item2; var extent = viewer.GetLayerInfo(0)?.ProjectedExtent; if (extent is not null) viewer.ViewExtent = extent.Value; reset.Enabled = true; overlay.Show(this); Reset(); } catch (Exception ex) { MessageBox.Show(this, ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Error); } finally { UseWaitCursor = false; } }
    void Reset() { if (busy) return; points.Clear(); nodes.Clear(); result = null; routeList.Items.Clear(); roadList.Items.Clear(); summary.Text = "Select a depot and at least two visits."; vehicles.Maximum = 1; vehicles.Value = 1; calculate.Enabled = false; overlay.SetState(points, [], null, 0); viewer.ActiveTool = GeoKernelViewerTool.Route; status.Text = "Click the map to add the depot."; }
    void MapClicked(object? s, GeoKernelMapMouseEventArgs e) { if (busy || engine is null || e.Tool != GeoKernelViewerTool.Route || (e.ButtonOrButtons & 1) == 0) return; var candidates = nodes.Count == 0 ? component : engine.Reachable(nodes[^1]); var n = engine.Nearest(candidates, OptimizationEngine.ToWgs(new(e.WorldPoint.X, e.WorldPoint.Y)), 2000); if (n is null) { MessageBox.Show(this, "No reachable road node was found near this point.", Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } if (nodes.Count > 0 && nodes[^1] == n.Id) return; nodes.Add(n.Id); points.Add(OptimizationEngine.ToWeb(n.Position)); result = null; routeList.Items.Clear(); roadList.Items.Clear(); overlay.SetState(points, [], null, 0); var visits = Math.Max(0, points.Count - 1); summary.Text = $"Depot + {visits} visit(s) selected."; vehicles.Maximum = Math.Max(1, visits); calculate.Enabled = points.Count >= 3; status.Text = points.Count == 1 ? "Depot selected. Add at least two visit points." : $"Visit {visits} added. Add another visit or optimize."; }
    async Task Optimize() { if (busy || engine is null || nodes.Count < 3) return; var vehicleCount = (int)vehicles.Value; busy = true; calculate.Enabled = reset.Enabled = false; status.Text = "Optimizing service vehicle routes..."; try { result = await Task.Run(() => engine.Optimize(nodes, vehicleCount)); if (result is null) { MessageBox.Show(this, "The selected visits cannot form connected vehicle routes.", Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } routeList.Items.Clear(); for (var i = 0; i < result.Vehicles.Count; i++) { var v = result.Vehicles[i]; var labels = string.Join(" → ", v.Order.Select(x => x == 0 ? "D" : x.ToString()).Append("D")); routeList.Items.Add($"Vehicle {i + 1}: {labels}\r\n{v.Route.Distance / 1000:0.00} km • {v.Route.Time / 60:0.0} min"); } summary.Text = $"{result.Vehicles.Count} vehicles • {points.Count - 1} visits\r\nFleet distance: {result.TotalDistance / 1000:0.00} km\r\nLongest route: {result.LongestDistance / 1000:0.00} km\r\nCombined driving time: {result.TotalTime / 60:0.0} min"; overlay.SetState(points, result.Vehicles.Select(x => x.Route.Geometry).ToArray(), null, 0); routeList.SelectedIndex = 0; status.Text = "Routes optimized for all service vehicles."; } finally { busy = false; reset.Enabled = true; calculate.Enabled = nodes.Count >= 3; } }
    void SelectVehicle() { if (result is null || routeList.SelectedIndex < 0 || routeList.SelectedIndex >= result.Vehicles.Count) return; var index = routeList.SelectedIndex; overlay.SetState(points, result.Vehicles.Select(x => x.Route.Geometry).ToArray(), result.Vehicles[index].Route.Geometry, index); roadList.Items.Clear(); foreach (var (step, i) in result.Vehicles[index].Steps.Select((x, i) => (x, i))) roadList.Items.Add($"{i + 1}. {step.Name}\r\n    {(step.Distance >= 1000 ? $"{step.Distance / 1000:0.0} km" : $"{step.Distance:0} m")}"); }
    void SelectRoad() { if (result is null || routeList.SelectedIndex < 0 || roadList.SelectedIndex < 0) return; var steps = result.Vehicles[routeList.SelectedIndex].Steps; if (roadList.SelectedIndex < steps.Count) overlay.SetHighlight(steps[roadList.SelectedIndex].Geometry); }
    sealed class Overlay : Form { readonly GeoKernelViewerControl v; IReadOnlyList<RoutePoint> stops = []; IReadOnlyList<IReadOnlyList<RoutePoint>> routes = []; IReadOnlyList<RoutePoint>? highlight; int active; static readonly Color[] colors = [Color.FromArgb(37, 99, 235), Color.FromArgb(249, 115, 22), Color.FromArgb(147, 51, 234), Color.FromArgb(8, 145, 178), Color.FromArgb(219, 39, 119), Color.FromArgb(101, 163, 13), Color.FromArgb(202, 138, 4), Color.FromArgb(79, 70, 229)]; public Overlay(GeoKernelViewerControl x) { v = x; FormBorderStyle = FormBorderStyle.None; ShowInTaskbar = false; BackColor = Color.Fuchsia; TransparencyKey = Color.Fuchsia; StartPosition = FormStartPosition.Manual; } protected override bool ShowWithoutActivation => true; protected override CreateParams CreateParams { get { var p = base.CreateParams; p.ExStyle |= 0x08000020 | 0x80; return p; } } public void SyncBounds() { if (!Visible || !v.IsHandleCreated) return; Bounds = new Rectangle(v.PointToScreen(Point.Empty), v.ClientSize); Invalidate(); } public void SetState(IReadOnlyList<RoutePoint> s, IReadOnlyList<IReadOnlyList<RoutePoint>> r, IReadOnlyList<RoutePoint>? h, int a) { stops = s.ToArray(); routes = r; highlight = h; active = a; Invalidate(); } public void SetHighlight(IReadOnlyList<RoutePoint>? h) { highlight = h; Invalidate(); } protected override void OnShown(EventArgs e) { base.OnShown(e); SyncBounds(); } protected override void OnPaint(PaintEventArgs e) { e.Graphics.SmoothingMode = SmoothingMode.AntiAlias; for (var i = 0; i < routes.Count; i++) if (i != active) Line(e.Graphics, routes[i], Color.FromArgb(135, colors[i % colors.Length]), 3); if (active >= 0 && active < routes.Count) Line(e.Graphics, routes[active], colors[active % colors.Length], 5); if (highlight is not null) { Line(e.Graphics, highlight, Color.FromArgb(210, 255, 214, 10), 10); Line(e.Graphics, highlight, Color.FromArgb(220, 38, 38), 4); } for (var i = 0; i < stops.Count; i++) Marker(e.Graphics, stops[i], i); } void Line(Graphics g, IReadOnlyList<RoutePoint> p, Color c, float w) { if (p.Count < 2) return; var a = p.Select(Screen).Where(x => float.IsFinite(x.X) && float.IsFinite(x.Y)).ToArray(); if (a.Length < 2) return; using var pen = new Pen(c, w) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round }; g.DrawLines(pen, a); } void Marker(Graphics g, RoutePoint x, int i) { var p = Screen(x); var fill = i == 0 ? Color.FromArgb(34, 197, 94) : Color.FromArgb(245, 158, 11); var outline = i == 0 ? Color.FromArgb(20, 83, 45) : Color.FromArgb(120, 53, 15); using var b = new SolidBrush(fill); using var pen = new Pen(outline, 2); g.FillEllipse(b, p.X - 8, p.Y - 8, 16, 16); g.DrawEllipse(pen, p.X - 8, p.Y - 8, 16, 16); TextRenderer.DrawText(g, i == 0 ? "D" : i.ToString(), SystemFonts.DefaultFont, new Rectangle((int)p.X - 8, (int)p.Y - 8, 16, 16), Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter); } PointF Screen(RoutePoint p) { var x = v.WorldToScreen(p.X, p.Y); return new((float)x.X, (float)x.Y); } }
}
